      <main className="p-6 max-w-6xl mx-auto">
        {/* Filtros */}
        <div className="bg-white rounded-xl border p-4 mb-6 flex flex-wrap gap-3 items-end">
          <div>
            <label className="block text-xs font-medium text-gray-600 mb-1">Empresa</label>
            <select
